<script setup lang="ts">
import{onMounted,reactive,ref}from'vue';import{enterpriseApi}from'../services/enterprise'
const data=ref<any>({rooms:[],accounts:[],anchors:[]}),tab=ref('rooms'),show=ref(false),loading=ref(true),error=ref(''),notice=ref('');const room=reactive({name:'',region:''}),account=reactive({display_name:'',room_id:'',platform_account_ref:'',target_region_id:'us-los-angeles'}),anchor=reactive({display_name:'',employee_ref:''})
async function load(){loading.value=true;error.value='';try{data.value=await enterpriseApi.options()}catch(e:any){error.value=e.message}finally{loading.value=false}}
async function save(){try{if(tab.value==='rooms')await enterpriseApi.createRoom(room);else if(tab.value==='accounts')await enterpriseApi.createAccount({...account,room_id:account.room_id?Number(account.room_id):null});else await enterpriseApi.createAnchor(anchor);show.value=false;await load();notice.value=`已创建${tab.value==='rooms'?'直播间':tab.value==='accounts'?'开播账号':'主播档案'}，现在可以在设备详情中完成绑定。`}catch(e:any){error.value=e.message}}
onMounted(load)
</script>
<template><div class="page-stack"><section class="panel"><header class="panel-head"><div><span class="eyebrow">LIVE OPERATIONS STRUCTURE</span><h2>直播中心</h2><p>管理直播间、开播账号和主播的内部识别资料；不保存 TikTok 密码、Cookie 或浏览器会话。</p></div><button class="primary" @click="show=!show">新增{{tab==='rooms'?'直播间':tab==='accounts'?'开播账号':'主播'}}</button></header><div class="segmented"><button :class="{active:tab==='rooms'}" @click="tab='rooms';show=false">直播间 {{data.rooms.length}}</button><button :class="{active:tab==='accounts'}" @click="tab='accounts';show=false">开播账号 {{data.accounts.length}}</button><button :class="{active:tab==='anchors'}" @click="tab='anchors';show=false">主播 {{data.anchors.length}}</button></div><form v-if="show" class="member-form" @submit.prevent="save"><template v-if="tab==='rooms'"><label>直播间名称<input v-model="room.name" required></label><label>业务地区<input v-model="room.region" placeholder="例如 美国西部"></label></template><template v-else-if="tab==='accounts'"><label>账号内部名称<input v-model="account.display_name" required></label><label>关联直播间<select v-model="account.room_id"><option value="">暂不关联</option><option v-for="x in data.rooms" :value="String(x.id)">{{x.name}}</option></select></label><label>平台公开标识<input v-model="account.platform_account_ref" placeholder="可留空，不填写密码"></label><label>目标地区<input v-model="account.target_region_id"></label></template><template v-else><label>主播姓名/代号<input v-model="anchor.display_name" required></label><label>企业员工编号<input v-model="anchor.employee_ref" placeholder="可留空"></label></template><footer><button type="button" @click="show=false">取消</button><button class="primary">保存</button></footer></form><div v-if="notice" class="success-banner">{{notice}}</div><div v-if="error" class="state-inline error"><b>直播结构操作未完成</b><span>{{error}}</span><button @click="load">重新加载</button></div><div v-else-if="loading" class="skeleton-table"><i v-for="n in 6" class="skeleton"></i></div><div v-else-if="!data[tab].length" class="empty-state"><b>还没有{{tab==='rooms'?'直播间':tab==='accounts'?'开播账号':'主播档案'}}</b><p>新增后即可在设备详情中关联，绑定历史会完整保留。</p></div><div v-else class="entity-grid"><article v-for="x in data[tab]" :key="x.id"><span class="entity-icon">{{tab==='rooms'?'⌂':tab==='accounts'?'T':'人'}}</span><div><b>{{x.name||x.display_name}}</b><p v-if="tab==='rooms'">{{x.region||'未设置地区'}}</p><p v-else-if="tab==='accounts'">{{x.room_id?`直播间 #${x.room_id}`:'未关联直播间'}}</p><p v-else>主播档案 #{{x.id}}</p></div><span class="source-chip enabled">正常</span></article></div></section></div></template>
